"""Islamiat (Ikhtiari) XII PDF68: pp.126–127 — ahadith 33 (explanation), 34, 35. Run: python class12_iski_page068.py"""
from class12_iski_common import BOOK, Builder, rec, P, AR


def p68():
    b = Builder()
    b.h('Explanation', 'تشریح', 'تشریح')
    P(b, [('From the hadith it is known that pleasing the parents is obligatory and displeasing them is unlawful, because in their pleasure lies the pleasure of Allah and in their displeasure the displeasure of Allah. Allah the Exalted in the Holy Quran has mentioned the right of parents joined with His own right. "Be grateful to Me and to your parents" (Luqman 14). At another place Allah the Exalted says: "And your Lord has commanded that you worship none but Him and do good to your parents" (Al-Isra 17:23). The Messenger of Allah ﷺ said: shall I not tell you the greatest of the major sins? He said this three times. The Companions submitted: why not, O Messenger of Allah ﷺ! He ﷺ said: associating partners with Allah and grieving the parents. (Sahih Bukhari)', 'اس حدیث سے معلوم ہوتا ہے کہ والدین کو راضی کرنا فرض ہے اور انہیں ناراض کرنا حرام ہے کیونکہ ان کی رضا میں اللہ کی رضا اور ان کی ناراضگی میں اللہ کی ناراضگی ہے۔ اللہ تعالیٰ نے قرآن مجید میں اپنے حق کے ساتھ والدین کا حق ملا کر ذکر فرمایا ہے۔ ”میرا اور اپنے ماں باپ کا شکر ادا کر“ (لقمان ۱۴) ایک اور جگہ اللہ تعالیٰ ارشاد فرماتے ہیں ”اور تیرے رب نے حکم دیا کہ اس کے علاوہ کسی کی عبادت نہ کرو اور ماں باپ کے ساتھ احسان کرو“۔ (الاسراء ۱۷: ۲۳) رسول اللہ صلی اللہ علیہ وآلہٖ وسلم نے فرمایا کہ میں تمہیں اکبر الکبائر نہ بتاؤں تین دفعہ فرمایا صحابہؓ نے عرض کیا کیوں نہیں یا رسول اللہ صلی اللہ علیہ وآلہٖ وسلم! آپ صلی اللہ علیہ وآلہٖ وسلم نے ارشاد فرمایا اللہ کے ساتھ شریک ٹھہرانا اور والدین کو ستانا (صحیح بخاری)', 'له دې حدیث معلومېږي چې د مور و پلار خوشالول فرض او ناراضه کول یې حرام دي، ځکه د هغوی په رضا کې د الله رضا او د هغوی په ناخوښۍ کې د الله ناخوښي ده. الله تعالی په قرآن مجید کې د خپل حق سره د مور و پلار حق یوځای یاد کړی: «زما او د خپل مور و پلار شکر ادا کړه» (لقمان ۱۴). په بل ځای کې الله تعالی فرمایي: «او ستا رب حکم کړی چې له هغه پرته د بل چا عبادت مه کوئ او له مور و پلار سره احسان وکړئ» (الاسراء ۱۷: ۲۳). د الله رسول ﷺ وفرمایل: ایا تاسو ته تر ټولو لویه ګناه ونه ښیم؟ درې ځله یې وفرمایل. صحابه وو عرض وکړ: ولې نه، اې د الله رسوله ﷺ! هغه ﷺ وفرمایل: له الله سره شریک نیول او مور و پلار ځورول. (صحیح بخاري)'),
          ('The command of the parents will be obeyed only when it is not against the command of Allah the Exalted. If it involves disobedience to Allah, then the command of the parents will not be obeyed — for example, if the parents command doing such a deed which Allah the Exalted has forbidden, or stop one from such a deed which Allah the Exalted has made obligatory on everyone, then their word will not be obeyed.', 'والدین کا حکم صرف اس وقت مانا جائے گا جب وہ اللہ تعالیٰ کے حکم کے خلاف نہ ہو اگر اللہ کی نافرمانی ہوتی ہو تو والدین کا حکم نہیں مانا جائے گا مثلاً والدین ایسا کام کرنے کا حکم دیں جس سے اللہ تعالیٰ نے منع فرمایا ہے یا ایسے کام سے روکیں جو اللہ تعالیٰ نے ہر ایک پر فرض کیا ہے تو ان کی بات نہیں مانی جائے گی۔', 'د مور و پلار حکم یوازې هغه وخت منل کېږي چې د الله تعالی د حکم خلاف نه وي. که د الله نافرماني پکې وي، نو د مور و پلار حکم نه منل کېږي — لکه که مور و پلار د داسې کار حکم وکړي چې الله تعالی ترې منع کړې، یا له داسې کار منع کړي چې الله تعالی پر هر چا فرض کړی، نو خبره یې نه منل کېږي.')])
    b.h('Hadith no. 34', 'حدیث نمبر 34', 'حدیث نمبر ۳۴')
    AR(b, 'عَنْ عَبْدِ اللّٰهِ بْنِ عَمْرٍو رَضِيَ اللّٰهُ عَنْهُمَا قَالَ: جَآءَ رَجُلٌ اِلَى النَّبِيِّ صَلَّى اللّٰهُ عَلَيْهِ وَآلِهٖ وَسَلَّمَ يَسْتَاْذِنُهٗ فِي الْجِهَادِ، فَقَالَ: اَحَيٌّ وَالِدَاكَ؟ قَالَ: نَعَمْ، قَالَ فَفِيْهِمَا فَجَاهِدْ', 'صحیح مسلم')
    b.p('Translation: It is narrated from Abdullah bin Amr (may Allah be pleased with him) that a man came to the Noble Prophet ﷺ and asked permission to go for jihad. He ﷺ asked: are your parents alive? He said: yes. He ﷺ said: in their service lies your jihad.', 'ترجمہ: عبداللہ بن عمرو رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نبی اکرم صلی اللہ علیہ وآلہٖ وسلم کے پاس آیا اور جہاد میں جانے کی اجازت طلب کی، آپ صلی اللہ علیہ وآلہٖ وسلم نے پوچھا کیا تمہارے والدین زندہ ہیں؟ کہنے لگا: جی ہاں، آپ صلی اللہ علیہ وآلہٖ وسلم نے فرمایا: انکی خدمت میں ہی تمہارا جہاد ہے۔', 'ژباړه: له عبدالله بن عمرو رضي الله عنه روایت دی چې یو سړی نبي اکرم ﷺ ته راغی او جهاد ته د تګ اجازه یې وغوښته. هغه ﷺ وپوښتل: ایا مور و پلار دې ژوندي دي؟ ویې ویل: هو. هغه ﷺ وفرمایل: د هغوی په خدمت کې ستا جهاد دی.')
    r1 = rec(b, 2, 126, 68, [126])
    t = Builder()
    t.h('Explanation', 'تشریح', 'تشریح')
    t.p('Probably this matter had been revealed to the Messenger of Allah ﷺ, or for some reason he had a doubt about him, that this man\'s parents were in need of his service and he had come for jihad leaving them without their permission; therefore he ﷺ gave him this command, that he go back home and serve his parents, because in such a state the service of parents comes first for him. Drawing this conclusion from this hadith would be wrong, that whoever has parents should never go out of the house for jihad and for some service of the religion, and that only those people should engage in jihad and in the service of the religion whose parents are not alive. Among the noble Companions who used to do jihad with the Messenger of Allah ﷺ, a large number were of those whose parents were alive.', 'غالباً رسول اللہ صلی اللہ علیہ وآلہٖ وسلم پر یہ بات منکشف ہو گئی تھی یا کسی وجہ سے اس کے بارے میں شبہ ہو گیا تھا کہ اس آدمی کے ماں باپ اس کی خدمت کے محتاج ہیں اور یہ ان کو چھوڑ کے اُن کی اجازت کے بغیر جہاد کے لیے آ گیا ہے اس لیے آپ نے اس کو یہ حکم دیا کہ وہ گھر واپس جا کر ماں باپ کی خدمت کرے کیونکہ ایسی حالت میں اس کے لیے ماں باپ کی خدمت مقدم ہے۔ اس حدیث سے یہ نتیجہ نکالنا غلط ہوگا کہ جس کسی کے ماں باپ ہوں وہ جہاد اور دین کی کسی خدمت کے لیے کبھی گھر سے باہر نہ نکلے اور صرف وہی لوگ جہاد میں اور دین کے خدمت میں لگیں جن کے ماں باپ نہ ہوں۔ رسول اللہ صلی اللہ علیہ وآلہٖ وسلم کے ساتھ جو صحابہ کرامؓ جہاد کرتے تھے ان میں بڑی تعداد انہی کی ہوتی تھی جن کے ماں باپ زندہ ہوتے تھے۔', 'ښايي د الله رسول ﷺ ته دا خبره ښکاره شوې وه، یا د کوم دلیل له امله یې د هغه په اړه شک پیدا شوی و، چې د دې سړي مور و پلار د هغه خدمت ته اړ دي او دی یې پرېښي او بې له اجازې یې جهاد ته راغلی؛ نو هغه ﷺ ورته حکم وکړ چې کور ته ستون شي او د مور و پلار خدمت وکړي، ځکه په داسې حالت کې د هغه لپاره د مور و پلار خدمت مخکې دی. له دې حدیث دا پایله اخیستل به غلط وي چې د چا مور و پلار وي، هغه دې هېڅکله د جهاد او د دین د کوم خدمت لپاره له کوره ونه وځي، او یوازې هغه خلک دې په جهاد او د دین په خدمت کې ولګېږي چې مور و پلار یې نه وي. له رسول الله ﷺ سره چې کومو صحابه کرامو جهاد کاوه، په هغوی کې لوی شمېر د هغو و چې مور و پلار یې ژوندي وو.')
    t.h('Hadith no. 35', 'حدیث نمبر 35', 'حدیث نمبر ۳۵')
    AR(t, 'عَنْ عَبْدِ اللّٰهِ ابْنِ عُمَرَ رَضِيَ اللّٰهُ عَنْهُمَا اَنَّ رَسُوْلَ اللّٰهِ صَلَّى اللّٰهُ عَلَيْهِ وَسَلَّمَ قَالَ: اَلْمُسْلِمُ اَخُو الْمُسْلِمِ لَا يَظْلِمُهٗ، وَلَا يُسْلِمُهٗ، وَمَنْ كَانَ فِيْ حَاجَةِ اَخِيْهِ كَانَ اللّٰهُ فِيْ حَاجَتِهٖ، وَمَنْ فَرَّجَ عَنْ مُسْلِمٍ كُرْبَةً فَرَّجَ اللّٰهُ عَنْهُ كُرْبَةً مِّنْ كُرُبَاتِ يَوْمِ الْقِيٰمَةِ وَمَنْ سَتَرَ مُسْلِمًا سَتَرَهُ اللّٰهُ يَوْمَ الْقِيٰمَةِ', 'صحیح البخاری کتاب المظالم حدیث نمبر ۲۴۴۲')
    t.p('Translation: It is narrated from Ibn Umar (may Allah be pleased with him) that the Messenger of Allah ﷺ said: a Muslim is the brother of another Muslim; he neither wrongs him nor abandons him in any calamity. And whoever remains engaged in fulfilling the need of his brother, Allah the Exalted keeps fulfilling his needs; and whoever removes the hardship of some Muslim, Allah the Exalted will remove from him a hardship among the hardships of the Day of Judgement; and whoever covers (the faults of) some Muslim, Allah the Exalted will cover him on the Day of Judgement.', 'ترجمہ: ابن عمرؓ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وآلہٖ وسلم نے فرمایا کہ ایک مسلمان دوسرے مسلمان کا بھائی ہے نہ اس پر ظلم کرے اور نہ کسی مصیبت میں اس کا ساتھ چھوڑے اور جو شخص اپنے بھائی کی حاجت روائی میں لگا رہتا ہے اللہ تعالیٰ اس کی حاجتیں پوری کرتا رہتا ہے اور جو شخص کسی مسلمان کی سختی کو دور کرتا ہے اللہ تعالیٰ قیامت کی سختیوں میں سے اس کی سختی دور کرے گا اور جو شخص کسی مسلمان کی پردہ پوشی کرے اللہ تعالیٰ قیامت کے دن اس کی پردہ پوشی کرے گا۔', 'ژباړه: له ابن عمر رضي الله عنه روایت دی چې د الله رسول ﷺ وفرمایل: یو مسلمان د بل مسلمان ورور دی؛ نه پرې ظلم کوي او نه یې په کوم مصیبت کې یوازې پرېږدي. او څوک چې د خپل ورور د اړتیا په پوره کولو بوخت وي، الله تعالی د هغه اړتیاوې پوره کوي؛ او څوک چې د کوم مسلمان سختي لرې کړي، الله تعالی به یې د قیامت له سختیو یوه سختي لرې کړي؛ او څوک چې د کوم مسلمان پرده‌پوشي وکړي، الله تعالی به د قیامت په ورځ د هغه پرده‌پوشي وکړي.')
    t.h('Explanation', 'تشریح', 'تشریح')
    t.p('In this blessed hadith it is stated that Muslims are brothers among themselves. The bond of religion is (above) all …', 'اس حدیثِ مبارکہ میں اس بات کا بیان ہے کہ مسلمان آپس میں بھائی بھائی ہوتے ہیں۔ دین کا رشتہ سب سے', 'په دې مبارک حدیث کې د دې خبرې بیان دی چې مسلمانان په خپل منځ کې وروڼه دي. د دین اړیکه تر ټولو …')
    BOOK.save(68, [(2, r1), (2, rec(t, 2, 127, 68, [127]))], issues=[{'id': 'iski12-pdf068', 'unit': 2, 'printedPage': 126,
               'description': 'Student handwriting on p.126 excluded. Quranic references in the explanation are printed as "(لقمان ۱۴)" and "(الاسراء ۱۷: ۲۳)".'}])


